layout: default
---
<!-- _layouts/paper_project.html -->
<!-- Academic Project Page Template adapted for Jekyll -->

{% if page._styles %}
<!-- Page/Post style -->
<style type="text/css">
  {{ page._styles }}
</style>
{% endif %}

<div class="paper-project">
  <!-- Hero Section -->
  <section class="hero">
    <div class="hero-body">
      <div class="container is-max-desktop">
        <div class="columns is-centered">
          <div class="column has-text-centered">
            <h1 class="title is-1 publication-title">{{ page.title }}</h1>

            {% if page.authors %}
            <div class="is-size-5 publication-authors">
              {% for author in page.authors %}
                <span class="author-block">
                  {% if author.url %}
                    <a href="{{ author.url }}" target="_blank">{{ author.name }}</a>
                  {% else %}
                    {{ author.name }}
                  {% endif %}
                  {% if author.equal_contrib %}<sup>*</sup>{% endif %}
                  {% unless forloop.last %},{% endunless %}
                </span>
              {% endfor %}
            </div>
            {% endif %}

            {% if page.affiliations %}
            <div class="is-size-5 publication-authors">
              {% for affiliation in page.affiliations %}
                <span class="author-block">{{ affiliation.name }}{% if affiliation.conference %}<br>{{ affiliation.conference }}{% endif %}</span>
                {% unless forloop.last %}<br>{% endunless %}
              {% endfor %}
              {% if page.equal_contrib_note %}
                <span class="eql-cntrb"><small><br><sup>*</sup>{{ page.equal_contrib_note }}</small></span>
              {% endif %}
            </div>
            {% endif %}

            {% if page.links %}
            <div class="column has-text-centered">
              <div class="publication-links">
                {% for link in page.links %}
                  <span class="link-block">
                    <a href="{{ link.url }}" target="_blank" class="external-link button is-normal is-rounded is-dark">
                      <span class="icon">
                        <i class="{{ link.icon }}"></i>
                      </span>
                      <span>{{ link.name }}</span>
                    </a>
                  </span>
                {% endfor %}
              </div>
            </div>
            {% endif %}
          </div>
        </div>
      </div>
    </div>
  </section>

  {% if page.teaser_video %}
  <!-- Teaser Video Section -->
  <section class="hero teaser">
    <div class="container is-max-desktop">
      <div class="hero-body">
        <video poster="{% if page.teaser_video.poster %}{{ page.teaser_video.poster }}{% endif %}" 
               id="teaser-video" 
               {% if page.teaser_video.autoplay %}autoplay{% endif %} 
               {% if page.teaser_video.controls %}controls{% endif %} 
               {% if page.teaser_video.muted %}muted{% endif %} 
               {% if page.teaser_video.loop %}loop{% endif %} 
               height="100%">
          <source src="{{ page.teaser_video.url }}" type="video/mp4">
        </video>
        {% if page.teaser_video.caption %}
        <h2 class="subtitle has-text-centered">
          {{ page.teaser_video.caption }}
        </h2>
        {% endif %}
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.abstract %}
  <!-- Abstract Section -->
  <section class="section hero is-light">
    <div class="container is-max-desktop">
      <div class="columns is-centered has-text-centered">
        <div class="column is-four-fifths">
          <h2 class="title is-3">Abstract</h2>
          <div class="content has-text-justified">
            <p>{{ page.abstract }}</p>
          </div>
        </div>
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.image_carousel %}
  <!-- Image Carousel Section -->
  <section class="hero is-small">
    <div class="hero-body">
      <div class="container">
        {% if page.image_carousel.title %}
        <h2 class="title is-3">{{ page.image_carousel.title }}</h2>
        {% endif %}
        <div id="results-carousel" class="carousel results-carousel">
          {% for image in page.image_carousel.images %}
          <div class="item">
            <img src="{{ image.url }}" alt="{{ image.alt | default: 'Project Image' }}"/>
            {% if image.caption %}
            <h2 class="subtitle has-text-centered">
              {{ image.caption }}
            </h2>
            {% endif %}
          </div>
          {% endfor %}
        </div>
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.youtube_video %}
  <!-- YouTube Video Section -->
  <section class="hero is-small is-light">
    <div class="hero-body">
      <div class="container">
        <h2 class="title is-3">{{ page.youtube_video.title | default: 'Video Presentation' }}</h2>
        <div class="columns is-centered has-text-centered">
          <div class="column is-four-fifths">
            <div class="publication-video">
              <iframe src="{{ page.youtube_video.url }}" 
                      frameborder="0" 
                      allow="autoplay; encrypted-media" 
                      allowfullscreen></iframe>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.video_carousel %}
  <!-- Video Carousel Section -->
  <section class="hero is-small">
    <div class="hero-body">
      <div class="container">
        <h2 class="title is-3">{{ page.video_carousel.title | default: 'Video Carousel' }}</h2>
        <div id="video-carousel" class="carousel results-carousel">
          {% for video in page.video_carousel.videos %}
          <div class="item item-video{{ forloop.index }}">
            <video poster="{% if video.poster %}{{ video.poster }}{% endif %}" 
                   id="video{{ forloop.index }}" 
                   {% if video.autoplay %}autoplay{% endif %} 
                   {% if video.controls %}controls{% endif %} 
                   {% if video.muted %}muted{% endif %} 
                   {% if video.loop %}loop{% endif %} 
                   height="100%">
              <source src="{{ video.url }}" type="video/mp4">
            </video>
            {% if video.caption %}
            <h2 class="subtitle has-text-centered">
              {{ video.caption }}
            </h2>
            {% endif %}
          </div>
          {% endfor %}
        </div>
      </div>
    </div>
  </section>
  {% endif %}

  <!-- Main Content (from markdown) -->
  {% if content and content != empty %}
  <section class="section">
    <div class="container is-max-desktop">
      <div class="content">
        {{ content }}
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.poster %}
  <!-- Poster Section -->
  <section class="hero is-small is-light">
    <div class="hero-body">
      <div class="container">
        <h2 class="title">{{ page.poster.title | default: 'Poster' }}</h2>
        <iframe src="{{ page.poster.url }}" 
                width="100%" 
                height="{{ page.poster.height | default: '550' }}">
        </iframe>
      </div>
    </div>
  </section>
  {% endif %}

  {% if page.bibtex %}
  <!-- BibTeX Citation Section -->
  <section class="section" id="BibTeX">
    <div class="container is-max-desktop content">
      <h2 class="title">BibTeX</h2>
      <pre><code>{{ page.bibtex }}</code></pre>
    </div>
  </section>
  {% endif %}

  {% if page.acknowledgments %}
  <!-- Acknowledgments Section -->
  <section class="section">
    <div class="container is-max-desktop content">
      <h2 class="title">Acknowledgments</h2>
      <p>{{ page.acknowledgments }}</p>
    </div>
  </section>
  {% endif %}
</div>

<!-- Include required CSS and JS for the template -->
{% if page.include_bulma_css %}
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bulma@0.9.4/css/bulma.min.css">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/jpswalsh/academicons@1/css/academicons.min.css">
{% endif %}

{% if page.include_carousel_js %}
<script src="https://ajax.googleapis.com/ajax/libs/jquery/3.5.1/jquery.min.js"></script>
<script>
// Carousel functionality (simplified version)
$(document).ready(function() {
  if ($('.carousel').length > 0) {
    // Basic carousel implementation
    $('.carousel').each(function() {
      var $carousel = $(this);
      var $items = $carousel.find('.item');
      var currentIndex = 0;

      if ($items.length > 1) {
        setInterval(function() {
          $items.eq(currentIndex).hide();
          currentIndex = (currentIndex + 1) % $items.length;
          $items.eq(currentIndex).show();
        }, 3000);
      }
    });
  }
});
</script>
{% endif %}

<style>
/* Basic styles for the paper project layout */
.paper-project .hero {
  padding: 3rem 1.5rem;
}

.paper-project .publication-title {
  margin-bottom: 1rem;
}

.paper-project .publication-authors {
  margin-bottom: 1rem;
}

.paper-project .author-block {
  margin-right: 1rem;
}

.paper-project .publication-links {
  margin-top: 1rem;
}

.paper-project .link-block {
  margin: 0.5rem;
}

.paper-project .button {
  margin: 0.25rem;
}

.paper-project .teaser video {
  width: 100%;
  border-radius: 8px;
}

.paper-project .carousel {
  position: relative;
  overflow: hidden;
}

.paper-project .carousel .item {
  display: none;
  text-align: center;
}

.paper-project .carousel .item:first-child {
  display: block;
}

.paper-project .carousel img,
.paper-project .carousel video {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
}

.paper-project .publication-video iframe {
  width: 100%;
  height: 400px;
  border-radius: 8px;
}

.paper-project iframe {
  border-radius: 8px;
}

.paper-project pre {
  background: #f5f5f5;
  padding: 1rem;
  border-radius: 8px;
  overflow-x: auto;
}

.paper-project .section {
  padding: 3rem 1.5rem;
}

.paper-project .container.is-max-desktop {
  max-width: 1152px;
  margin: 0 auto;
}

.paper-project .columns.is-centered {
  justify-content: center;
}

.paper-project .column.is-four-fifths {
  width: 80%;
}

.paper-project .has-text-centered {
  text-align: center;
}

.paper-project .has-text-justified {
  text-align: justify;
}

.paper-project .is-light {
  background-color: #fafafa;
}

.paper-project .title.is-1 {
  font-size: 3rem;
  font-weight: 600;
  line-height: 1.125;
}

.paper-project .title.is-3 {
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.125;
}

.paper-project .subtitle {
  font-size: 1.25rem;
  font-weight: 400;
  line-height: 1.25;
  margin-top: 1rem;
}

/* Responsive design */
@media screen and (max-width: 768px) {
  .paper-project .title.is-1 {
    font-size: 2rem;
  }

  .paper-project .publication-video iframe {
    height: 250px;
  }

  .paper-project .button {
    margin: 0.25rem 0;
    display: block;
    width: 100%;
  }
}
</style>"}

