/* Paper project layout styles - adapted for al-folio theme */
.post .authors {
    color: var(--global-text-color-light);
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.post .authors a {
    color: var(--global-theme-color);
    text-decoration: none;
}

.post .authors a:hover {
    color: var(--global-hover-color);
    text-decoration: underline;
}

.post .affiliations {
    color: var(--global-text-color-light);
    font-size: 1rem;
    margin-bottom: 1rem;
}

.post .equal-contrib {
    color: var(--global-text-color-light);
    margin-top: 0.5rem;
}

.post .paper-links {
    margin: 1.5rem 0;
}

.post .paper-links .btn {
    margin: 0.25rem 0.5rem 0.25rem 0;
    background-color: var(--global-theme-color);
    color: var(--global-hover-text-color);
    border: none;
}

.post .paper-links .btn:hover {
    background-color: var(--global-hover-color);
    color: var(--global-hover-text-color);
}

.post .teaser-video video {
    width: 100%;
    max-height: 500px;
}

.post .abstract-section {
    background-color: var(--global-card-bg-color);
    padding: 2rem;
    border-radius: 6px;
    border: 1px solid var(--global-divider-color);
}

.post .abstract-content p {
    text-align: justify;
    line-height: 1.6;
}

.post .carousel-container {
    position: relative;
    overflow: hidden;
    border-radius: 6px;
}

.post .carousel-item {
    display: none;
    text-align: center;
}

.post .carousel-item.active {
    display: block;
}

.post .carousel-item img,
.post .carousel-item video {
    width: 100%;
    height: auto;
}

.post .video-container {
    position: relative;
    width: 100%;
    height: 0;
    padding-bottom: 56.25%; /* 16:9 aspect ratio */
    overflow: hidden;
    border-radius: 6px;
}

.post .video-container iframe {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border: none;
}

.post .poster-section iframe {
    border: 1px solid var(--global-divider-color);
    border-radius: 6px;
}

.post .bibtex-section .highlight {
    margin: 1rem 0;
}

.post .bibtex-section pre {
    background-color: var(--global-code-bg-color);
    border: 1px solid var(--global-divider-color);
    border-radius: 6px;
    padding: 1rem;
    overflow-x: auto;
    font-size: 0.875rem;
}

.post .bibtex-section code {
    background-color: transparent;
    color: var(--global-text-color);
}

.post h2 {
    color: var(--global-text-color);
    margin: 2rem 0 1rem 0;
    font-weight: 600;
}

.post .mb-4 {
    margin-bottom: 2rem;
}

/* Navigation buttons for carousels */
.post .carousel-container:hover .carousel-nav {
    opacity: 1;
}

.post .carousel-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    background-color: rgba(0, 0, 0, 0.5);
    color: white;
    border: none;
    padding: 10px 15px;
    cursor: pointer;
    border-radius: 50%;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 10;
}

.post .carousel-nav:hover {
    background-color: rgba(0, 0, 0, 0.8);
}

.post .carousel-nav.prev {
    left: 10px;
}

.post .carousel-nav.next {
    right: 10px;
}

/* Responsive design */
@media screen and (max-width: 768px) {
    .post .paper-links .btn {
        display: block;
        width: 100%;
        margin: 0.5rem 0;
    }

    .post .abstract-section {
        padding: 1.5rem;
    }

    .post .carousel-nav {
        opacity: 1;
    }
}
</style>"
  }
]}

